function safeStringify(value: unknown): string {
  try {
    return JSON.stringify(value);
  } catch {
    return String(value);
  }
}

function prettifySchemaError(error: z.ZodError): string {
  return error.issues
    .map(issue => {
      const lines = [`✖ ${issue.message}`];
      if (issue.path?.length) {
        lines.push(`  -> 路径: ${issue.path.join('.')}`);
      }
      if ('input' in issue && issue.input !== undefined) {
        lines.push(`  -> 输入: ${safeStringify(issue.input)}`);
      }
      return lines.join('\n');
    })
    .join('\n');
}

function reportMvuSchemaError(level: 'error' | 'warn', content: string, title: string) {
  toastr[level === 'warn' ? 'warning' : 'error'](content.replaceAll('\n', '<br>'), `[MVU zod]${title}`, {
    escapeHtml: false,
  });
  console[level](`${title}\n${content}`);
}

function trimQuotesAndBackslashes(string: string): string {
  return string.replace(/^[\\"'` ]*(.*?)[\\"'` ]*$/, '$1');
}

function parsePath(string: string): string {
  return trimQuotesAndBackslashes(string).replace(/^(?:stat_data|status_current_variables)\./, '');
}

function parseCommandValue(string: unknown): unknown {
  if (typeof string !== 'string') {
    return string;
  }

  const trimmed = string.trim();

  if (trimmed === 'true') return true;
  if (trimmed === 'false') return false;
  if (trimmed === 'null') return null;
  if (trimmed === 'undefined') return undefined;

  try {
    return JSON.parse(trimmed);
  } catch {
    if ((trimmed.startsWith('{') && trimmed.endsWith('}')) || (trimmed.startsWith('[') && trimmed.endsWith(']'))) {
      try {
        const result = new Function(`return ${trimmed};`)();
        if (_.isObject(result) || Array.isArray(result)) {
          return result;
        }
      } catch {
        // fall through
      }
    }
  }

  try {
    return YAML.parse(trimmed);
  } catch {
    return trimQuotesAndBackslashes(string);
  }
}

export function registerMvuSchema(input: z.ZodType<Record<string, any>> | (() => z.ZodType<Record<string, any>>)) {
  const unwrapSchema = () => {
    const originalSchema = typeof input === 'function' ? input() : input;
    const schema = originalSchema instanceof z.ZodObject ? z.looseObject(originalSchema.shape) : originalSchema;
    if (typeof registerVariableSchema === 'function') {
      registerVariableSchema(z.object({ stat_data: schema }), { type: 'message' });
    }
    return schema;
  };

  unwrapSchema();

  eventOn('mag_variable_initialized', (variables, swipeId) => {
    const schema = unwrapSchema();
    try {
      const result = schema.safeParse(_.get(variables, 'stat_data', {}), { reportInput: true });
      if (result.success) {
        variables.stat_data = { ...variables.stat_data, ...result.data };
        return;
      }
      reportMvuSchemaError('error', z.prettifyError(result.error), `开局 '${swipeId + 1}' 变量初始化失败`);
    } catch (error) {
      const currentError = error as Error;
      reportMvuSchemaError(
        'error',
        currentError.stack ? currentError.stack : `${currentError.name}: ${currentError.message}`,
        `第 ${swipeId + 1} 条开场白的变量初始化失败`,
      );
    }
  });

  eventOn('mag_command_parsed_for_zod', (variables: Mvu.MvuData, commands: Mvu.CommandInfo[]) => {
    const schema = unwrapSchema();
    const notificationEnabled = Boolean($('#mvu_notification_error').prop('checked'));

    const checkSchema = (data: any, command: Mvu.CommandInfo, shouldToastr: boolean) => {
      let errorMessage = '';
      try {
        const result = schema.safeParse(data, { reportInput: true });
        if (result.success) {
          return result.data;
        }
        errorMessage = prettifySchemaError(result.error);
      } catch (error) {
        const currentError = error as Error;
        errorMessage = currentError.stack ? currentError.stack : `${currentError.name}: ${currentError.message}`;
      }

      if (notificationEnabled && shouldToastr) {
        reportMvuSchemaError('warn', errorMessage, `发生变量更新错误，可能需要重Roll: ${command.full_match}`);
      }
      return null;
    };

    const isReadonlyPath = (path: string | string[]) => {
      const normalizedPath = typeof path === 'string' ? _.toPath(path) : path;
      return normalizedPath.some(part => part.startsWith('_'));
    };

    const applyCommand = (data: any, command: Mvu.CommandInfo): Record<string, any> | null => {
      switch (command.type) {
        case 'set': {
          if (command.args.length === 3) {
            command.args.splice(1, 1);
          }
          const path = parsePath(command.args[0]);
          if (isReadonlyPath(path)) return null;
          if (path) {
            _.set(data, path, parseCommandValue(command.args[1]));
          } else {
            data = parseCommandValue(command.args[1]);
          }
          return checkSchema(data, command, true);
        }
        case 'add': {
          const path = parsePath(command.args[0]);
          if (!path || isReadonlyPath(path)) return null;
          const oldValue = _.get(data, path);
          if (typeof oldValue !== 'number') {
            if (notificationEnabled) {
              reportMvuSchemaError(
                'warn',
                [`✖ 不能对非数字类型 '${typeof oldValue}' 进行加减运算`, `  -> 路径: ${path}`, `  -> 原值: ${safeStringify(oldValue)}`].join('\n'),
                `发生变量更新错误，可能需要重Roll: ${command.full_match}`,
              );
            }
            return null;
          }
          const deltaValue = Number(parseCommandValue(command.args[1]));
          _.update(data, path, value => value + deltaValue);
          return checkSchema(data, command, true);
        }
        case 'insert': {
          const path = parsePath(command.args[0]);
          if (isReadonlyPath(path)) return null;
          const keyOrIndex = parseCommandValue(command.args[1]);
          const value = parseCommandValue(command.args.at(-1));

          const insert = (targetData: any, shouldToastr: boolean) => {
            const collection = path === '' ? targetData : _.get(targetData, path);
            const isArray = _.isArray(collection);
            if (command.args.length === 2) {
              if (isArray) {
                collection.push(value);
              } else {
                _.assign(collection, value);
              }
            } else if (isArray) {
              collection.splice(keyOrIndex === '-' ? collection.length : Number(keyOrIndex), 0, value);
            } else {
              collection[String(keyOrIndex)] = value;
            }
            return checkSchema(targetData, command, shouldToastr);
          };

          const collection = path === '' ? data : _.get(data, path);
          const isNil = _.isNil(collection);
          if (!isNil && !_.isArray(collection) && !_.isPlainObject(collection)) return null;
          if (!isNil) return insert(data, true);

          const filled = _(klona(data));
          const resultAsObject = insert(filled.set(path, {}).value(), false);
          if (resultAsObject) return resultAsObject;
          return insert(filled.set(path, []).value(), true);
        }
        case 'delete': {
          const path = command.args.map(parsePath).join('.');
          const pathArray = _.toPath(path);
          if (isReadonlyPath(pathArray)) return null;
          const parentPath = _.dropRight(pathArray).join('.');
          if (_.isArray(_.get(data, parentPath))) {
            _.pullAt(_.get(data, parentPath), Number(_(pathArray).last()));
          } else {
            _.unset(data, path);
          }
          return checkSchema(data, command, true);
        }
        case 'move': {
          const fromPath = parsePath(command.args[0]);
          const toPath = parsePath(command.args[1]);
          if (isReadonlyPath(fromPath) || isReadonlyPath(toPath) || !_.has(data, fromPath)) return null;
          const value = _.get(data, fromPath);
          const afterDelete = applyCommand(data, { ...command, type: 'delete', args: [fromPath] });
          if (afterDelete === null) return null;
          return applyCommand(afterDelete, { ...command, type: 'set', args: [toPath, value] });
        }
      }
      return null;
    };

    const consumedIndices: number[] = [];
    commands.forEach((command, index) => {
      const current = klona(variables.stat_data);
      const nextData = applyCommand(current, command);
      if (nextData !== null && !_.isEqual(nextData, _.pick(variables.stat_data, Object.keys(nextData)))) {
        variables.stat_data = { ...variables.stat_data, ...nextData };
        consumedIndices.push(index);
      }
    });

    _.pullAt(commands, consumedIndices);
  });

  eventOn('mag_command_parsed_ended_for_zod', (_variables, commands: Mvu.CommandInfo[]) => {
    commands.length = 0;
  });

  eventOn('mag_variable_update_ended_for_zod', variables => {
    _.set(variables, 'schema', '没有用别管这个');
    _.unset(variables, 'display_data');
    _.unset(variables, 'delta_data');
  });

  console.info('变量结构注册成功');
}

